window.AG_CHAPTERS["01"] = {"id":"01","title":"A-Lian&#39;s Cough","titleZh":"阿蓮的咳嗽","patient":{"name":"A-Lian 阿蓮","sprite":"girl"},"scene":{"img":"art/scene-treatment.jpg","key":"rain"},"pattern":"Wind-Cold invading the Lung 風寒襲肺","principle":"release the exterior, diffuse the Lung","tongue":"pale-red, thin white coating","pulseNote":{"en":"The beat rises to meet your finger the moment you touch — and feels taut, like a stretched cord.","zh":"輕取即得，脈來繃緊如按琴弦"},"needleAsk":{"en":"Needle <b>Lièquē LU7</b>. Tap its exact location.","zh":"行針 — 點出穴位精確位置"},"target":{"id":"LU7","zh":"列缺","py":"Lièquē","x":262,"y":497,"note":"<b>列缺 Lièquē LU7</b> — 1.5 cun above the wrist crease, superior to the radial styloid. Luo-Connecting point of the Lung; confluent point opening the Ren mai.<br>腕橫紋上1.5寸，橈骨莖突上方。肺經絡穴，八脈交會通任脈。"},"hints":{"ask":{"en":"A three-day illness on the surface asks: <b>chills or fever?</b> <b>sweating?</b> <b>what does the phlegm look like?</b>","zh":"新病三日在表，當問：惡寒發熱孰重？有汗無汗？痰之色質？"},"look":{"en":"On the tongue, a <b>thin white</b> coat means the pathogen is still outside. Yellow would mean it has turned to heat.","zh":"舌苔薄白，邪尚在表；轉黃則化熱。"},"pulse":{"en":"An exterior pattern floats. Cold makes it tight, heat makes it fast. She was caught in cold rain.","zh":"表證脈浮。寒則兼緊，熱則兼數。她淋的是冷雨。"},"dx":{"en":"Ask in order: <b>exterior or interior</b> → <b>cold or heat</b> → <b>which organ</b>. Three days is not long.","zh":"依序問：表裡 → 寒熱 → 病在何臟。三天，不算久。"},"rx":{"en":"Release the exterior and open the Lung. Think <b>distal</b> points that reach the surface and the head.","zh":"解表宣肺。想能達表、達頭項的遠端穴。"},"tech":{"en":"An exterior excess pattern is <b>drained</b>, not tonified — and it is not deep.","zh":"表實當瀉不當補，且不宜深刺。"}},"reactions":[{"who":"master","en":"Master Shen does not look up. \"Go on.\"","zh":"參師父沒有抬頭。「繼續。」"},{"who":"patient","en":"A-Lian coughs into her sleeve and waits politely.","zh":"阿蓮往袖子裡咳了一聲，客氣地等著。"},{"who":"boy","en":"The herb boy quietly puts back the jar he had already reached for.","zh":"藥童把剛拿下的藥罐悄悄放了回去。"},{"who":"master","en":"\"Hm.\" Master Shen sets down his brush.","zh":"「唔。」參師父擱下筆。"},{"who":"patient","en":"\"Should I... come back another day?\" A-Lian asks.","zh":"「我⋯⋯要不要改天再來？」阿蓮問。"},{"who":"master","en":"\"The illness is three days old,\" he says. \"It is not hiding.\"","zh":"「病才三天，」他說，「它沒有躲。」"}],"remedy":{"ask":"cold_heat","look":"cold_heat","pulse":"cold_heat","dx":"excess_def","rx":"channel_organ","tech":"cold_heat"},"reward":{"cardEn":"Diffuse &amp; Release","cardZh":"宣肺解表","cardTxt":"For an exterior Wind-Cold pattern, open the Lung&#39;s dispersing function and push the pathogen back out through the surface.","herbId":"shengjiang","herbEn":"Fresh Ginger","herbZh":"生薑","herbImg":"art/card-shengjiang.jpg","sprite":"art/sprite-renshen-jump.webp","herbTxt":"Acrid and warm — in TCM food therapy it is the everyday kitchen ally for early wind-cold, taken as a warm tea."},"endings":{"three":["Two days later A-Lian is back at the silk shop. \"The stiffness in my neck went first,\" she says, \"then the cough.\"<br><b>Master Shen:</b> \"You read the surface correctly. Most students rush inward and miss what is right in front of them.\"","兩天後，阿蓮回到絲行。「先是脖子鬆了，然後咳嗽就好了。」<br><b>參師父：</b>「你把表證看準了。多數學生急著往裡鑽，反而錯過眼前的東西。」"],"two":["A-Lian sleeps through the night, though the cough lingers a little.<br><b>Master Shen:</b> \"Not bad. Go back over your reasoning — one link was loose.\"","阿蓮夜裡能睡了，咳嗽還有一點。<br><b>參師父：</b>「不差。回頭把推理再走一遍，有一環鬆了。」"],"one":["The cough is unchanged.<br><b>Master Shen:</b> \"Do not be discouraged. Go back and look again — the clues were all there.\"","咳嗽沒有起色。<br><b>參師父：</b>「別氣餒。回去再看一次，線索本來都在。」"],"titles":["A-Lian Picks Up Her Needle","A-Lian Rests Easier","A-Lian Will Need Another Visit"]},"script":[{"w":"master","en":"You've swept this floor for a month. Today you meet a patient.","cn":"你掃了一個月的地。今天，你要見病人了。"},{"w":"master","en":"Remember: we do not treat a cough. We treat the person who is coughing — and the pattern behind it.","cn":"記住：我們治的不是咳嗽，是咳嗽的這個人，以及背後的證。"},{"w":"patient","en":"Doctor… I'm A-Lian, I embroider at the silk shop. I've been coughing for three days.","cn":"大夫⋯⋯我是阿蓮，在絲行做繡活。咳了三天了。"},{"w":"patient","en":"It started after I got caught in the rain on the way home. Now I can't hold my needle steady.","cn":"那天回家路上淋了雨，之後就這樣。現在連針都拿不穩。"},{"w":"master","en":"Rain. Cold. Wind. — A beginning is a clue, but never the whole answer. Ask her properly.","cn":"雨、寒、風。起病是線索，卻不是答案。好好問診。"}],"qa":[{"q":"Do you feel cold, or feverish?","cq":"你怕冷還是發熱？","good":1,"a":"Chills much worse than fever. I keep wanting another blanket.","ca":"惡寒重、發熱輕，一直想再蓋條被子。","clue":{"en":"Chills stronger than fever","zh":"惡寒重發熱輕"},"note":"Chills > fever points to an <b>exterior cold</b> pattern. 惡寒重發熱輕＝表寒。"},{"q":"Are you sweating?","cq":"有沒有出汗？","good":1,"a":"No sweat at all, even under the blanket.","ca":"完全沒汗，蓋著被子也不出汗。","clue":{"en":"No sweating","zh":"無汗"},"note":"No sweating with chills = <b>Wind-Cold</b> rather than Wind-Heat. 無汗屬風寒表實。"},{"q":"What does the phlegm look like?","cq":"痰是什麼樣子？","good":1,"a":"Thin and white, easy to spit out.","ca":"痰稀白，容易咳出來。","clue":{"en":"Thin white phlegm","zh":"痰稀白"},"note":"Thin white phlegm = <b>cold</b>. Thick yellow would mean heat. 痰稀白屬寒，黃稠屬熱。"},{"q":"Does your head or neck ache?","cq":"頭項痛不痛？","good":1,"a":"Yes — the back of my head and my neck feel stiff and sore.","ca":"後腦和脖子又緊又痛。","clue":{"en":"Stiff head and neck","zh":"頭項強痛"},"note":"Stiff occiput and neck = the <b>Taiyang</b> exterior. 頭項強痛為太陽表證。"},{"q":"How is your appetite lately?","cq":"最近胃口如何？","good":0,"a":"About the same as usual, I suppose.","ca":"跟平常差不多吧。","clue":"","note":"Reasonable to ask, but it adds nothing here — the illness is only three days old and on the surface. 問得合理，但此時無助辨證。"},{"q":"Do you have night sweats and a dry throat at 3am?","cq":"半夜盜汗、咽乾嗎？","good":0,"a":"No, nothing like that.","ca":"沒有這些。","clue":"","note":"These probe <b>Yin deficiency</b> — a chronic interior pattern, not a three-day exterior one. 此問屬陰虛內傷，與新病表證不符。"}],"look":[{"t":"Pale-red body, thin white coating","c":"舌淡紅，苔薄白","ok":1,"clue":{"en":"Pale-red tongue, thin white coat","zh":"舌淡紅苔薄白"},"note":"Correct. A near-normal body with a <b>thin white coat</b> = the pathogen is still on the <b>exterior</b> and has not turned to heat. 苔薄白＝病邪在表，未化熱。"},{"t":"Red body, yellow greasy coating","c":"舌紅，苔黃膩","ok":0,"note":"That would indicate <b>damp-heat</b> in the interior — the coating here is clearly thin and white. 黃膩苔主濕熱，與本案不符。"},{"t":"Pale swollen body with teeth marks","c":"舌淡胖有齒痕","ok":0,"note":"That suggests <b>Spleen Qi / Yang deficiency</b> with dampness — a chronic interior pattern. 齒痕舌主脾虛濕盛，屬內傷久病。"}],"pulse":[{"t":"Floating and tight 浮緊","ok":1,"clue":{"en":"Floating, tight pulse","zh":"脈浮緊"},"note":"Correct. <b>Floating</b> = the pathogen is on the exterior; <b>tight</b> = cold constricting the vessels. Floating-tight is the signature pulse of Wind-Cold. 浮主表，緊主寒，浮緊為風寒表實之脈。"},{"t":"Floating and rapid 浮數","ok":0,"note":"Floating-rapid would mean Wind-<b>Heat</b>. Nothing here is hot — no thirst, no sore throat, no yellow phlegm. 浮數主風熱，本案無熱象。"},{"t":"Deep and thready 沉細","ok":0,"note":"Deep-thready indicates an <b>interior deficiency</b> pattern, not a fresh exterior invasion. 沉細主裡虛，與新感表證不符。"}],"dx":[{"ask":"Step 1 — Eight Principles. Where is it, and what is its nature?<br><small style=\"color:var(--ink-soft)\">八綱辨證：病位？病性？</small>","opts":[{"t":"Exterior · Cold · Excess","c":"表 · 寒 · 實","ok":1,"note":"Correct. Three days old, chills>fever, no sweat, floating-tight pulse, thin white coat — <b>exterior cold excess</b>. 新病、惡寒重、無汗、脈浮緊＝表寒實證。"},{"t":"Interior · Heat · Excess","c":"裡 · 熱 · 實","ok":0,"note":"No heat signs and no interior signs are present. 無熱象、無裡證。"},{"t":"Exterior · Cold · Deficiency","c":"表 · 寒 · 虛","ok":0,"note":"Close on location and nature — but <b>no sweating</b> marks this as excess (表實), not deficiency (表虛, which sweats). 無汗屬表實；表虛則有汗。"}]},{"ask":"Step 2 — Zang-Fu. Which organ is disturbed, and by what?<br><small style=\"color:var(--ink-soft)\">臟腑辨證：病在何臟？何邪？</small>","opts":[{"t":"Wind-Cold invading the Lung","c":"風寒襲肺","ok":1,"note":"Correct. The Lung governs Qi and rules the exterior — wind-cold blocks its dispersing and descending function, so she coughs. 肺主氣、司呼吸、外合皮毛；風寒束表，肺失宣降而咳。"},{"t":"Phlegm-Damp obstructing the Lung","c":"痰濕阻肺","ok":0,"note":"That pattern brings copious sticky phlegm and a greasy coat, usually chronic. 痰濕阻肺痰多黏膩、苔膩，多屬久病。"},{"t":"Liver Fire invading the Lung","c":"肝火犯肺","ok":0,"note":"That brings irritability, bitter taste, red eyes, rapid wiry pulse. 肝火犯肺見急躁、口苦、脈弦數。"}]}],"rx":[{"id":"LU7","t":"Lièquē LU7 列缺","ok":1,"note":"Luo point of the Lung, confluent with the Ren mai — the classic point to diffuse the Lung and release the exterior. 肺經絡穴，宣肺解表要穴。"},{"id":"LI4","t":"Hégǔ LI4 合谷","ok":1,"note":"Yuan point of the Large Intestine, paired with LU7 as host-guest — strongly releases the exterior. 大腸原穴，與列缺原絡配穴，解表力強。"},{"id":"BL12","t":"Fēngmén BL12 風門","ok":1,"note":"\"Wind Gate\" — expels wind from the surface; excellent with moxa for wind-cold. 祛風散寒，風寒證常配灸法。"},{"id":"KI3","t":"Tàixī KI3 太溪","ok":0,"note":"Kidney Yuan point — tonifies Kidney Yin. Tonifying in a fresh exterior excess pattern risks retaining the pathogen. 補腎陰；表實新感用補法有閉門留寇之虞。"},{"id":"SP9","t":"Yīnlíngquán SP9 陰陵泉","ok":0,"note":"Drains damp — but this is cold on the exterior, not dampness. 利濕，本案非濕證。"},{"id":"LR3","t":"Tàichōng LR3 太衝","ok":0,"note":"Courses Liver Qi — no Liver signs in this case. 疏肝，本案無肝證。"}],"tech":[{"t":"Reducing method, then moxa 瀉法後加灸","ok":1,"note":"Correct. An <b>excess</b> exterior pattern calls for reducing; moxa warms and scatters the cold. 表實證用瀉法，風寒加灸溫散。"},{"t":"Reinforcing method, retain 30 min 補法久留針","ok":0,"note":"Reinforcing an excess exterior pattern risks trapping the pathogen inside. 表實用補法，恐閉門留寇。"},{"t":"Bleed the well point 井穴放血","ok":0,"note":"Bleeding well points suits <b>heat</b> patterns such as an acute sore throat, not wind-cold. 井穴放血用於熱證咽喉腫痛。"}]};
